public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {
        if (this.ModuleInventCustVend == ModuleInventCustVend::Vend 
        &&  this.METInvoiceConsolidationByRebateType
        && !this.METVendAccount)
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateDeal, METVendAccount)));
        }
    }

    return ret;
}

